mapper.delete:
delete from history
where user_id = #{userId}
  and music_id = #{musicId}

delete from history
where user_id = #{userId}
  and id not in (
    select id from (
                       select id
                       from history
                       where user_id = #{userId}
                       order by play_time desc
                           limit #{limit}
                   ) t
)

